import{_ as i,P as s,d as o,e as r,x as t,q as n}from"./chunks/framework.BRr8VP3a.js";const g=JSON.parse('{"title":"Part 6 Operation and Evolution","description":"","frontmatter":{"title":"Part 6 Operation and Evolution","xkChars":0,"xkWords":5491,"xkLessons":{"6.2.1":{"title":"Feedback delay changes the stability interval","lead":"A return can have an effect while the resulting dynamics fail to converge.","explanation":["For the specified recurrence x(t+1)=x(t)−k x(t−d), the book gives the exact asymptotic-stability condition 0<k<2sin[π/(4d+2)]. The delay d is a fixed nonnegative integer and the gain k is fixed. The condition concerns all finite initial histories in this particular linear model.","At k=0.8, delays zero and one lie inside their stability intervals; delays two and three do not. Under the all-one initial history, all four first updates equal 0.2. The return already has a model-internal effect, while long-run convergence differs.","Even stability leaves other questions open: transient peaks, resource costs, constraints, safety, and human acceptability. Time-varying delays, noise, saturation, external inputs, and nonlinear rules require a different analysis rather than silent reuse of the formula."],"distinctions":[{"leftTitle":"Feedback effect","leftText":"The return changes the next state relative to no return.","rightTitle":"Asymptotic stability","rightText":"Every finite initial history converges to zero under the stated model."}],"teachingExamples":[{"title":"Same gain, longer delay","text":"At k=0.8, the critical gains for d=0,1,2,3 are 2,1,approximately 0.618034,and approximately 0.445042. The first two cases are stable and the last two are not.","assumptions":"Fixed linear recurrence, no noise or saturation, finite initial history.","boundary":"The equality boundary is excluded; the values are not universal organizational thresholds."}],"boundaries":["An unstable model can still have special trajectories, such as an all-zero history, that do not grow.","The formal result does not certify a real controller or repair."],"questionAnswers":[{"question":"Does the minus sign guarantee stable correction?","answer":"No. Stability depends on the gain, delay, and the complete dynamics, not the sign alone.","basis":"Theory v2, §6.2.1, with the distinctions explained above."}],"caseLinks":[{"title":"C.10: full stability argument","href":"/en/theory/appendix-c#section-c-10"}],"sourceRefs":[{"section":"6.2.1","startLine":1382,"endLine":1389}],"sourceHash":"51795bb7988f2669a324a52666c320cfba1382f597f7b5c6a1431844572da1fb","sources":[{"id":"theory-v2-en","title":"Xikari: On Conditions, Structure, and Transformation — English reference edition","url":"/en/theory/part-06#section-6-2-1","source_type":"theory_source","version_or_date":"Theory v2, November 2026","locator":"§6.2.1; English reading edition, lines 1382–1389","claim_support":["The section’s definitions, argument, and conditions, interpreted in this guide."],"limits":["The Chinese original remains authoritative. This is a theory source, not independent empirical support for a real case."]}]},"6.3":{"title":"An update must be retained and used to support learning","lead":"One write-back, training event, or successful attempt cannot stand for the whole mechanism.","explanation":["Feedback-mediated learning links a return to a locatable update, the update’s retention or renewal in a carrier, actual later use, and a comparison for a declared task. A rule can be written and never used. A later success can also come from a new resource or easier task rather than the update.","The carried-learning route follows current skills, rules, parameters, memory, or structures across rounds. The historical-increment route adds the narrower G3 question beyond an explicit current representation. These routes must not borrow each other’s eligibility or treat positive G3 as a universal prerequisite for learning.","A practice may truly have changed while its later net effects remain uncertain. Learning on one task also does not establish independent transfer, fairness, or improvement across every affected position. State the achievement and the unresolved outcome separately."],"distinctions":[{"leftTitle":"A saved update","leftText":"Shows that a record or rule changed.","rightTitle":"Feedback-mediated learning","rightText":"Adds retention, actual later use, task comparison, and the required causal basis."}],"teachingExamples":[{"title":"The unused checklist","text":"Suppose an incident produces a better checklist, but later teams never open it. The document changed; its use cannot explain later performance. If use is documented, the outcome comparison still remains to be assessed.","assumptions":"Hypothetical process designed to separate storage from use.","boundary":"The example does not show that a real checklist is effective or ineffective."}],"boundaries":["Do not equate absent G3 support with absence of ordinary learning.","Training attendance, archive size, or a single success does not establish the specified mechanism."],"questionAnswers":[{"question":"Must supported participation be followed by success without support?","answer":"Only if independent transfer is the declared target. Necessary support can be part of a successfully completed task.","basis":"Theory v2, §6.3, with the distinctions explained above."}],"caseLinks":[{"title":"Flint: a changed procedure and open outcome questions","href":"/en/cases/flint-water-feedback"}],"sourceRefs":[{"section":"6.3","startLine":1390,"endLine":1407}],"sourceHash":"51795bb7988f2669a324a52666c320cfba1382f597f7b5c6a1431844572da1fb","sources":[{"id":"theory-v2-en","title":"Xikari: On Conditions, Structure, and Transformation — English reference edition","url":"/en/theory/part-06#section-6-3","source_type":"theory_source","version_or_date":"Theory v2, November 2026","locator":"§6.3; English reading edition, lines 1390–1407","claim_support":["The section’s definitions, argument, and conditions, interpreted in this guide."],"limits":["The Chinese original remains authoritative. This is a theory source, not independent empirical support for a real case."]}]},"6.6":{"title":"Recovery has several endpoints","lead":"Restored service, restored criteria, and replenished margins need separate evidence.","explanation":["Load must be compared with capacity of the relevant type, at the same position and within the relevant window. An adequate average can hide a critical local shortage. A short peak is not automatically a cumulative-damage mechanism.","For recovery, specify what returned, for whom, under which support conditions, and as of when. Restored visible output, the declared identity or functional criteria K/F, and internal margins are distinct. Spare parts, staff rest, maintenance backlog, financing, and burdens shifted outside the boundary may matter to the wider claim.","Continuing support does not make a restored function false. A later interruption also does not automatically negate an earlier bounded success. Investigate continued old damage, depleted reserves, support loss, a new shock, or a changed measurement boundary before deciding what must be revised."],"distinctions":[{"leftTitle":"A functioning service now","leftText":"A bounded availability result for specified users and conditions.","rightTitle":"Restored recovery margins","rightText":"Evidence that the relevant resources and capacity for continued operation or future recovery are available."}],"teachingExamples":[{"title":"Temporary power at one service point","text":"Assume temporary power restores the target service for observed users during a defined period. This is a real bounded recovery, while coverage of all former users and service after support expires remain unestablished.","assumptions":"Constructed example; actual availability within the stated scope is assumed.","boundary":"Necessary support should not be withdrawn just to make recovery look independent."}],"boundaries":["Do not replace the denominator of pre-event residents with current service users without saying so.","“False recovery” limits an overextended claim; it does not independently establish deception."],"questionAnswers":[{"question":"Does unrecovered data negate restored service availability?","answer":"No. The outcomes differ. Both the restored service and the remaining data loss must be reported accurately.","basis":"Theory v2, §6.6, with the distinctions explained above."}],"caseLinks":[{"title":"GitLab: service, data, and recovery arrangements","href":"/en/cases/gitlab-recovery"}],"sourceRefs":[{"section":"6.6","startLine":1438,"endLine":1453}],"sourceHash":"51795bb7988f2669a324a52666c320cfba1382f597f7b5c6a1431844572da1fb","sources":[{"id":"theory-v2-en","title":"Xikari: On Conditions, Structure, and Transformation — English reference edition","url":"/en/theory/part-06#section-6-6","source_type":"theory_source","version_or_date":"Theory v2, November 2026","locator":"§6.6; English reading edition, lines 1438–1453","claim_support":["The section’s definitions, argument, and conditions, interpreted in this guide."],"limits":["The Chinese original remains authoritative. This is a theory source, not independent empirical support for a real case."]}]},"6.10.1":{"title":"Formation, maintenance, recovery, and replication are different outcomes","lead":"Evidence that an arrangement started does not settle whether it lasts, recovers, or transfers.","explanation":["Formation concerns how an arrangement comes into being. Maintenance concerns what keeps it operating. Recovery concerns a specified function or identity after disruption. Replication concerns the result under a declared new realization or setting. Each needs its own target, conditions, window, and evidence.","A successful launch may rely on unusual founding resources. Routine operation may depend on maintenance labor that the launch record never measured. A recovery may meet a limited function while changing components. Replication may change the treatment itself when scale, implementation, or the object changes.","When replication fails, distinguish failure of the scheme itself, including the possibility that the original result was not caused by the scheme; deviation from the implementation specified beforehand; absence of a previously stated enabling condition; and a scale change that alters the treatment or object. Both implementation content and enabling conditions must be written before results and independently checkable. Inventing a missing condition after every failure shields the claim from correction.","An implementation deviation or missing enabling condition suggested only after failure remains a candidate for a later test. It does not revise the present result record. Whether an arrangement should be maintained, recovered, or replicated is also a separate normative judgment."],"distinctions":[{"leftTitle":"A new result","leftText":"Evidence for the specific formation, maintenance, recovery, or replication task.","rightTitle":"A wider mechanism claim","rightText":"Requires the evidence and conditions of that additional task."}],"teachingExamples":[{"title":"A pilot works, a larger program does not","text":"Suppose a pilot uses a declared staffing ratio. A later rollout uses a different ratio and process. Record the actual implementation change; do not call it an identical treatment or invent an unrecorded condition after failure.","assumptions":"Hypothetical comparison; the original conditions and actual difference are available.","boundary":"The distinction alone does not identify which mechanism caused the failure."}],"boundaries":["Formation does not prove maintenance, and recovery does not prove unchanged identity.","Retain successes within their supported task even when another outcome fails."],"questionAnswers":[{"question":"Can a failed replication be excused by any condition named afterward?","answer":"No. A relevant enabling condition must have been stated beforehand and be independently checkable; other explanations remain candidates requiring evidence.","basis":"Theory v2, §6.10.1, with the distinctions explained above."}],"caseLinks":[],"sourceRefs":[{"section":"6.10.1","startLine":1496,"endLine":1501}],"sourceHash":"51795bb7988f2669a324a52666c320cfba1382f597f7b5c6a1431844572da1fb","sources":[{"id":"theory-v2-en","title":"Xikari: On Conditions, Structure, and Transformation — English reference edition","url":"/en/theory/part-06#section-6-10-1","source_type":"theory_source","version_or_date":"Theory v2, November 2026","locator":"§6.10.1; English reading edition, lines 1496–1501","claim_support":["The section’s definitions, argument, and conditions, interpreted in this guide."],"limits":["The Chinese original remains authoritative. This is a theory source, not independent empirical support for a real case."]}]}}},"headers":[],"relativePath":"en/theory/part-06.md","filePath":"en/theory/part-06.md"}'),c={name:"en/theory/part-06.md"};function d(l,e,h,u,p,m){const a=s("SectionLesson");return o(),r("div",null,[e[0]||(e[0]=t("",1)),n(a,{section:"6.2.1"}),e[1]||(e[1]=t("",1)),n(a,{section:"6.3"}),e[2]||(e[2]=t("",1)),n(a,{section:"6.6"}),e[3]||(e[3]=t("",1)),n(a,{section:"6.10.1"}),e[4]||(e[4]=t("",3))])}const b=i(c,[["render",d]]);export{g as __pageData,b as default};
